/*
 * Ported from the Wayback captures of May 2021 roblox.com. The values below
 * were read from the archived rbxcdn stylesheets (main bundle, landing bundle,
 * navigation bundle, footer, modals, game-detail bundles) and from computed
 * styles of the archived landing, games, profile and game pages. Section
 * comments note where a rule comes from when it is not obvious.
 * Fonts and images are the 2021 rbxcdn originals, embedded as base64 so the
 * style makes no network requests of its own.
 */

/* ============================================================
   Fonts — Gotham SSm as shipped on the 2021 site
   ============================================================ */

@font-face   {
  font-family: "HCo Gotham SSm";
  src: url("  data:font/woff2;base64,") format("woff2");
  font-weight: 300;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "HCo Gotham SSm";
  src: url("  data:font/woff2;base64,") format("woff2");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "HCo Gotham SSm";
  src: url("  data:font/woff2;base64,") format("woff2");
  font-weight: 500;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "HCo Gotham SSm";
  src: url("  data:font/woff2;base64,") format("woff2");
  font-weight: 700;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "HCo Gotham SSm";
  src: url("  data:font/woff2;base64,") format("woff2");
  font-weight: 800;
  font-style: normal;
  font-display: swap;
}

/* ============================================================
   Design tokens
   ============================================================ */

:root {
  --rbx21-font: "HCo Gotham SSm", "Helvetica Neue", Helvetica, Arial, "Lucida Grande", sans-serif;
  --rbx21-green: #02b757;         /* theme-less primary base */
  --rbx21-green-hover: #3fc679;
  --rbx21-green-disabled: #a3e2bd;
  --rbx21-growth: #00b06f;        /* growth/play buttons after theming */
  --rbx21-blue: #00a2ff;          /* theme-less secondary base */
  --rbx21-blue-hover: #32b5ff;
  --rbx21-blue-disabled: #99daff;
  --rbx21-red: #f74b52;
  --rbx21-alert: #d86868;
  --rbx21-text: #393b3d;
  --rbx21-text-subtle: #606162;
  --rbx21-text-label: #b8b8b8;
  --rbx21-border: #b8b8b8;
  --rbx21-divider: #e3e3e3;
  --rbx21-page: #f2f4f5;
  --rbx21-header-bg: #dee1e3;
  --rbx21-header-border: #c7cbce;
  --rbx21-dark-page: #191b1d;
  --rbx21-dark-card: #232527;
  --rbx21-dark-footer: #111214;
  --rbx21-dark-muted: #bdbebe;
  --rbx21-input-dark: rgba(0, 0, 0, .7);
  --rbx21-input-border-dark: #707070;
  --rbx21-btn-border: #b8b8b8;
  --rbx21-new-badge: #f68802;
  --rbx21-sale-badge: #e2231a;
}

/* ============================================================
   Design-system token layer
   ============================================================ */

/*
 * The modern site's foundation components read semantic CSS variables.
 * Overriding them at the theme scopes carries the 2021 palette into every
 * design-system surface — including pages whose DOM could not be inspected
 * (the session-bound moderation screens, logged-in-only areas). Token names
 * were captured from the live page; values are the 2021 palette.
 */

body#rbx-body.light-theme {
  --color-content-emphasis: var(--rbx21-text) !important;
  --light-mode-content-emphasis: var(--rbx21-text) !important;
  --color-action-utility-foreground: var(--rbx21-text) !important;
  --light-mode-action-utility-foreground: var(--rbx21-text) !important;
  --color-action-standard-foreground: var(--rbx21-text) !important;
  --light-mode-action-standard-foreground: var(--rbx21-text) !important;
  --color-action-subtle-foreground: var(--rbx21-text-subtle) !important;
  --light-mode-action-subtle-foreground: var(--rbx21-text-subtle) !important;
  --color-action-link-foreground: var(--rbx21-blue) !important;
  --light-mode-action-link-foreground: var(--rbx21-blue) !important;
  --color-action-emphasis-background: var(--rbx21-growth) !important;
  --light-mode-action-emphasis-background: var(--rbx21-growth) !important;
  --light-mode-action-emphasis-foreground: #fff !important;
  --color-action-sub-emphasis-background: var(--rbx21-text) !important;
  --light-mode-action-sub-emphasis-background: var(--rbx21-text) !important;
  --color-action-standard-background: rgba(57, 59, 61, .12) !important;
  --light-mode-action-standard-background: rgba(57, 59, 61, .12) !important;
  --color-system-emphasis: var(--rbx21-growth) !important;
  --light-mode-system-emphasis: var(--rbx21-growth) !important;
  --color-action-subtle-border: var(--rbx21-text-subtle) !important;
  --color-stroke-emphasis: rgba(57, 59, 61, .3) !important;
  --light-mode-stroke-emphasis: rgba(57, 59, 61, .3) !important;
  --light-mode-stroke-default: rgba(57, 59, 61, .2) !important;
  --color-action-alert-foreground: var(--rbx21-red) !important;
  --light-mode-action-alert-foreground: var(--rbx21-red) !important;
  --color-navigation-background: var(--rbx21-header-bg) !important;
  --light-mode-navigation-background: var(--rbx21-header-bg) !important;
  --color-common-navigation-bar: var(--rbx21-header-bg) !important;
  --light-mode-common-navigation-bar: var(--rbx21-header-bg) !important;
  --color-surface-0: var(--rbx21-page);
  --light-mode-surface-0: var(--rbx21-page);
}

body#rbx-body.dark-theme   {
  --color-content-emphasis: #fff !important;
  --dark-mode-content-emphasis: #fff !important;
  --color-action-utility-foreground: #fff !important;
  --dark-mode-action-utility-foreground: #fff !important;
  --color-action-standard-foreground: #fff !important;
  --dark-mode-action-standard-foreground: #fff !important;
  --color-action-subtle-foreground: var(--rbx21-dark-muted) !important;
  --dark-mode-action-subtle-foreground: var(--rbx21-dark-muted) !important;
  --color-action-link-foreground: var(--rbx21-blue) !important;
  --dark-mode-action-link-foreground: var(--rbx21-blue) !important;
  --color-action-emphasis-background: var(--rbx21-growth) !important;
  --dark-mode-action-emphasis-background: var(--rbx21-growth) !important;
  --dark-mode-action-emphasis-foreground: var(--rbx21-text) !important;
  --color-action-sub-emphasis-background: #fff !important;
  --dark-mode-action-sub-emphasis-background: #fff !important;
  --color-action-standard-background: rgba(255, 255, 255, .12) !important;
  --dark-mode-action-standard-background: rgba(255, 255, 255, .12) !important;
  --color-system-emphasis: var(--rbx21-growth) !important;
  --dark-mode-system-emphasis: var(--rbx21-growth) !important;
  --color-action-subtle-border: var(--rbx21-dark-muted) !important;
  --color-stroke-emphasis: rgba(255, 255, 255, .3) !important;
  --dark-mode-stroke-emphasis: rgba(255, 255, 255, .3) !important;
  --dark-mode-stroke-default: rgba(255, 255, 255, .2) !important;
  --color-action-alert-foreground: var(--rbx21-red) !important;
  --dark-mode-action-alert-foreground: var(--rbx21-red) !important;
  --color-surface-0: var(--rbx21-dark-page);
  --dark-mode-surface-0: var(--rbx21-dark-page);
}

/* ============================================================
   Utility overrides
   ============================================================ */

/*
 * The foundation utilities read the tokens above, but some pages
 * re-declare those tokens in cascade layers, which beat unlayered
 * !important declarations. Overriding the utilities themselves avoids
 * that fight entirely.
 */

.bg-action-emphasis  {
  background-color: var(--rbx21-growth);
}
.bg-system-emphasis   {
  background-color: var(--rbx21-blue);
}

/* ============================================================
   Global styling
   ============================================================ */

/* Gotham SSm everywhere. The font token override catches the new
   design-system components; the body rule catches everything else. */
:root,
body#rbx-body {
  --config-theme-text-font: "HCo Gotham SSm";
}

body#rbx-body   {
  font-family: var(--rbx21-font);
  font-weight: 300;
  color: var(--rbx21-text);
}

/* Light theme page frame. The 2021 body carried a 15px gutter, which puts a
   visible margin between the header, content and footer. */
body#rbx-body:not(:has(#react-landing-container)) {
  background-color: var(--rbx21-page);
  padding: 15px;
}

/* The landing page is a full-bleed collage; it keeps no gutter. */
body#rbx-body:has(#react-landing-container) {
  background-color: var(--rbx21-dark-page);
  padding: 0;
}

/* Dark mode (site-wide) matches the 2021 dark palette. */
body#rbx-body.dark-theme {
  background-color: var(--rbx21-dark-page);
  color: #fff;
}

/* Content clears the fixed header by the header's own height. */
body#rbx-body .container-main {
  margin-top: 40px;
}
body#rbx-body .container-main.no-header-nav   {
  margin-top: 0;
}

/* Tint the legacy content wrapper. The 2021 width ladder
   (1338/1154/970px) is deliberately NOT ported: it squeezed the newer
   React pages (communities and friends) into a narrower column and broke
   their layouts, and those pages already size themselves. */
body#rbx-body .content {
  background-color: var(--rbx21-page);
  color: var(--rbx21-text);
}
body#rbx-body.dark-theme .content   {
  background-color: var(--rbx21-dark-page);
  color: #fff;
}

/* ============================================================
   Typography — the 2021 ramp
   ============================================================ */

body#rbx-body h1,
body#rbx-body h2,
body#rbx-body .font-title {
  font-size: 32px;
  font-weight: 800;
}
body#rbx-body h3,
body#rbx-body h4,
body#rbx-body .font-header-1   {
  font-size: 20px;
  font-weight: 700;
}
body#rbx-body .sort-header,
body#rbx-body .container-header h3   {
  font-size: 20px;
  font-weight: 700;
  color: var(--rbx21-text);
}
body#rbx-body .font-subheader-2   {
  font-size: 16px;
  font-weight: 500;
}
body#rbx-body .font-body,
body#rbx-body p   {
  font-size: 16px;
  font-weight: 400;
}
body#rbx-body .font-caption-header   {
  font-size: 12px;
  font-weight: 500;
}
body#rbx-body .font-caption-body   {
  font-size: 12px;
  font-weight: 400;
}
body#rbx-body .font-footer,
body#rbx-body .xsmall   {
  font-size: 10px;
  font-weight: 500;
}
body#rbx-body .font-bold,
body#rbx-body strong   {
  font-weight: 500;
}

@media (max-width: 767px) {
  body#rbx-body h1,
  body#rbx-body h2   {
    font-size: 24px;
  }
  body#rbx-body h3,
  body#rbx-body h4   {
    font-size: 16px;
  }
}

/* Themed text colors, verbatim from the bundle pairs. */
body#rbx-body.light-theme .text,
body#rbx-body.light-theme .text-default,
body#rbx-body.light-theme .text-description,
body#rbx-body.light-theme .text-info,
body#rbx-body.light-theme .text-secondary,
body#rbx-body.light-theme p {
  color: var(--rbx21-text-subtle);
}
body#rbx-body.light-theme .text-emphasis,
body#rbx-body.light-theme .text-sec,
body#rbx-body.light-theme .text-warning,
body#rbx-body.light-theme .text-lead,
body#rbx-body.light-theme .text-title   {
  color: var(--rbx21-text);
}
body#rbx-body.light-theme .text-muted,
body#rbx-body.light-theme .text-subheader   {
  color: rgba(0, 0, 0, .6);
}
body#rbx-body.dark-theme .text,
body#rbx-body.dark-theme .text-default,
body#rbx-body.dark-theme .text-description,
body#rbx-body.dark-theme .text-info,
body#rbx-body.dark-theme .text-secondary,
body#rbx-body.dark-theme p   {
  color: var(--rbx21-dark-muted);
}
body#rbx-body.dark-theme .text-emphasis,
body#rbx-body.dark-theme .text-sec,
body#rbx-body.dark-theme .text-warning,
body#rbx-body.dark-theme .text-lead,
body#rbx-body.dark-theme .text-title   {
  color: #fff;
}
body#rbx-body.dark-theme .text-muted,
body#rbx-body.dark-theme .text-subheader   {
  color: hsla(0, 0%, 100%, .7);
}

/* Links: #00a2ff blue with underline on hover; medium weight in Gotham. */
body#rbx-body a.text-link {
  color: var(--rbx21-blue);
  font-weight: 500;
}
body#rbx-body a.text-link:hover,
body#rbx-body a.text-link:focus   {
  color: var(--rbx21-blue);
  text-decoration: underline;
}body#rbx-body .light-theme .text-link-secondary,
body#rbx-body.light-theme .text-link-secondary {
  color: var(--rbx21-text-subtle);
}body#rbx-body .light-theme .text-link-secondary:hover,
body#rbx-body.light-theme .text-link-secondary:hover,
body#rbx-body .light-theme .text-link-secondary.active,
body#rbx-body.light-theme .text-link-secondary.active {
  color: var(--rbx21-text);
}body#rbx-body .dark-theme .text-link-secondary,
body#rbx-body.dark-theme .text-link-secondary {
  color: var(--rbx21-dark-muted);
}body#rbx-body .dark-theme .text-link-secondary:hover,
body#rbx-body.dark-theme .text-link-secondary:hover,
body#rbx-body .dark-theme .text-link-secondary.active,
body#rbx-body.dark-theme .text-link-secondary.active {
  color: #fff;
}

/* Labels, hints and errors. */
body#rbx-body .text-label {
  color: var(--rbx21-text-label);
  font-weight: 400;
}
body#rbx-body .text-date-hint   {
  font-size: 10px;
  font-weight: 400;
  color: var(--rbx21-text-label);
}
body#rbx-body .text-error   {
  color: var(--rbx21-red);
}
body#rbx-body .text-alert   {
  color: var(--rbx21-red);
}

body#rbx-body .see-all-link,
body#rbx-body .see-all-link-icon   {
  font-size: 16px;
  font-weight: 500;
}
body#rbx-body .text-footer.footer-note   {
  font-size: 10px;
  font-weight: 400;
  color: #b8b8b8;
}

/* ============================================================
   Header and navigation
   ============================================================ */

/* 2021 desktop ran a compact 40px header with the R mark; the tall
   90px bar with the full wordmark only appeared at 1688px and wider. */
#header.rbx-header {
  height: 40px;
  background-color: var(--rbx21-header-bg);
  border-bottom: 1px solid var(--rbx21-header-border);
}

#header .rbx-navbar-header   {
  max-width: 120px;
  margin: 0 12px;
}

#header .navbar-brand   {
  padding: 5px 0;
  height: auto;
}

/* Below 1688px the 2021 header used the tilted-square R mark. */
#header .icon-logo {
  display: none;
}
#header .icon-logo-r   {
  display: block;
  background-image: url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSIzMCIgaGVpZ2h0PSIzMCI+PHBhdGggZD0iTTguMyAzLjdMMy42IDIxLjhsMTguMSA0LjYgNC42LTE4LjEtMTgtNC42em04IDEzLjZsLTMuNS0uOS45LTMuNSAzLjUuOS0uOSAzLjV6IiBmaWxsPSIjMzkzYjNkIi8+PC9zdmc+");
  background-size: 30px 30px;
  background-position: 0 0;
  width: 30px;
  height: 30px;
}
body#rbx-body.dark-theme #header .icon-logo-r   {
  background-image: url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSIzMCIgaGVpZ2h0PSIzMCI+PHBhdGggZD0iTTguMyAzLjdMMy42IDIxLjhsMTguMSA0LjYgNC42LTE4LjEtMTgtNC42em04IDEzLjZsLTMuNS0uOS45LTMuNSAzLjUuOS0uOSAzLjV6IiBmaWxsPSIjZmZmIi8+PC9zdmc+");
}

/* Nav links that grow evenly, underlined on hover with a 2px rule. */
#header .rbx-navbar {
  margin: 4px auto;
}
#header .rbx-navbar li   {
  flex-grow: 1;
  text-align: center;
}
#header .nav-menu-title   {
  padding: 6px 9px;
  font-size: 16px;
  font-weight: 500;
  color: var(--rbx21-text);
}
#header .rbx-navbar li:hover   {
  border-bottom: 2px solid var(--rbx21-text);
}
#header .rbx-navbar li:hover .nav-menu-title   {
  background-color: transparent;
}
body#rbx-body.dark-theme #header .nav-menu-title   {
  color: #fff;
}

/* Right-hand cluster. */
#header .navbar-right {
  margin-right: 12px;
}
#header .rbx-navbar-right-nav   {
  margin: 4px auto;
  color: var(--rbx21-text);
}
/* Logged-in icon strip: the 2021 override pins it to the 28px line
   (the base margin:4px rule only applied to the login/logout cluster). */
#header .rbx-navbar-icon-group  {
  margin: 0;
  line-height: 28px;
  color: var(--rbx21-text);
}
#header .rbx-navbar-icon-group li .rbx-menu-item,
#header .rbx-navbar-icon-group li button,
#header .rbx-navbar-right-nav li .rbx-menu-item   {
  display: flex;
  align-items: center;
}
/* Padding belongs only to the direct legacy menu spans — putting it on the
   modern foundation buttons inflated them to 64x64 inside the 40px header. */
#header .rbx-navbar-icon-group li > .rbx-menu-item,
#header .rbx-navbar-right-nav li > .rbx-menu-item  {
  padding: 6px;
}
#header .rbx-navbar-icon-group li.navbar-icon-item   {
  display: flex;
  align-items: center;
}
#header .rbx-navbar-icon-group .notification-stream-indicator   {
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
}
#header .rbx-navbar-right-nav a   {
  color: var(--rbx21-text);
}

/* Roblox's header Download pill, and RoValra's injected navbar buttons,
   must sit inside the 2021 icon strip. The pill drops its black-modern
   fill for the outlined secondary look. */
#header .download-app-nav-item  {
  display: inline-flex;
  align-items: center;
  height: 28px;
  margin: 0 4px;
}
#header .download-app-nav-item button,
#header .download-app-nav-item a   {
  background-color: transparent;
  border: 1px solid var(--rbx21-text-subtle);
  color: var(--rbx21-text);
  border-radius: 8px;
  padding: 3px 12px;
  font-size: 16px;
  font-weight: 400;
}
body#rbx-body.dark-theme #header .download-app-nav-item button,
body#rbx-body.dark-theme #header .download-app-nav-item a   {
  background-color: transparent;
  border-color: var(--rbx21-dark-muted);
  color: var(--rbx21-dark-muted);
}

/* RoValra themes its injected icons with its own variable; feeding it the
   2021 ink keeps those icons in period inside the header. */
#header  {
  --rovalra-main-text-color: var(--rbx21-text);
}
body#rbx-body.dark-theme #header   {
  --rovalra-main-text-color: #fff;
}

/* Auth actions: green growth sign-up pill, plain-text log-in link. */
#header .rbx-navbar-signup,
#header #sign-up-button {
  background-color: var(--rbx21-growth);
  border: 1px solid var(--rbx21-growth);
  color: #fff;
  border-radius: 8px;
}
#header li.login-action > a,
#header li.login-action button   {
  background-color: transparent;
  border: 0;
  color: var(--rbx21-text);
  border-radius: 0;
}
#header li.login-action > a:hover,
#header li.login-action button:hover   {
  background-color: transparent;
  color: var(--rbx21-text);
}

/* Notification bubbles: dark ink on light theme, white on dark. */
body#rbx-body .light-theme .notification,
body#rbx-body .light-theme .notification-blue,
body#rbx-body .light-theme .notification-red {
  background-color: var(--rbx21-text);
  color: var(--rbx21-page);
  border-radius: 12px;
  font-size: 10px;
  font-weight: 500;
  border: 0;
}body#rbx-body .dark-theme .notification,
body#rbx-body.dark-theme .notification,
body#rbx-body .dark-theme .notification-blue,
body#rbx-body.dark-theme .notification-blue,
body#rbx-body .dark-theme .notification-red,
body#rbx-body.dark-theme .notification-red {
  background-color: #fff;
  color: var(--rbx21-dark-card);
  border-radius: 12px;
  font-size: 10px;
  font-weight: 500;
  border: 0;
}

/* The 2021 desktop header kept the menu trigger; the modern one only
   ships a hidden skip link there, so the three bars are drawn in CSS. */
#header #header-menu-icon.rbx-nav-collapse {
  display: block;
  width: 28px;
  height: 28px;
  margin: 6px 6px 0 0;
  padding: 0;
  background-image:
    linear-gradient(var(--rbx21-text) 2px, transparent 2px),
    linear-gradient(var(--rbx21-text) 2px, transparent 2px),
    linear-gradient(var(--rbx21-text) 2px, transparent 2px);
  background-size: 18px 2px;
  background-position: 5px 6px, 5px 13px, 5px 20px;
  background-repeat: no-repeat;
  cursor: pointer;
}
body#rbx-body.dark-theme #header #header-menu-icon.rbx-nav-collapse   {
  background-image:
    linear-gradient(#fff 2px, transparent 2px),
    linear-gradient(#fff 2px, transparent 2px),
    linear-gradient(#fff 2px, transparent 2px);
}

/* Search field: near-white pill with a hairline border. */
#header .navbar-search {
  background-color: transparent;
  border-radius: 8px;
  box-shadow: none;
}
#header .navbar-search .input-group   {
  height: 28px;
  background-color: transparent;
  border-radius: 8px;
}
#header #navbar-search-input   {
  background-color: rgba(255, 255, 255, .9);
  border: 1px solid rgba(57, 59, 61, .2);
  color: var(--rbx21-text);
  height: 28px;
}
body#rbx-body.dark-theme #header #navbar-search-input   {
  background-color: rgba(255, 255, 255, .1);
  border-color: rgba(255, 255, 255, .2);
}
#header #navbar-search-input::placeholder   {
  color: var(--rbx21-text-subtle);
}
#header .navbar-search .input-addon-btn   {
  background-color: transparent;
  border: 0;
}

/* Search suggestions. */
#header .navbar-search .new-dropdown-menu {
  background-color: var(--rbx21-page);
