  background-color: #f2f2f2;
}

/* ============================================================
   Left navigation drawer
   ============================================================ */

/* Recolors only: the modern drawer positions itself, and forcing the 2021
   fixed/width layout onto it overlaid newer pages (communities sidebar). */body#rbx-body .light-theme .rbx-left-col,
body#rbx-body.light-theme .rbx-left-col,
body#rbx-body .rbx-left-col.light-theme {
  background-color: var(--rbx21-header-bg);
  box-shadow: 0 0 8px 0 rgba(0, 0, 0, .1);
}body#rbx-body .light-theme .rbx-left-col li .text-nav:link,
body#rbx-body.light-theme .rbx-left-col li .text-nav:link,
body#rbx-body .light-theme .rbx-left-col li .text-nav:visited,
body#rbx-body.light-theme .rbx-left-col li .text-nav:visited,
body#rbx-body .light-theme .rbx-left-col li .text-nav:active,
body#rbx-body.light-theme .rbx-left-col li .text-nav:active {
  color: var(--rbx21-text);
}
body#rbx-body .rbx-left-col .rbx-scrollbar a   {
  font-weight: 500;
}
body#rbx-body .rbx-left-col li   {
  margin: 5px 0;
}body#rbx-body .dark-theme .rbx-left-col,
body#rbx-body.dark-theme .rbx-left-col,
body#rbx-body .rbx-left-col.dark-theme {
  background-color: var(--rbx21-dark-page);
  box-shadow: 0 0 8px 0 rgba(0, 0, 0, .3);
}body#rbx-body .dark-theme .rbx-left-col li .text-nav,
body#rbx-body.dark-theme .rbx-left-col li .text-nav {
  color: #fff;
}

/* ============================================================
   Footer
   ============================================================ */

body#rbx-body:not(:has(#react-landing-container)) #footer-container.container-footer {
  background-color: var(--rbx21-page);
}
body#rbx-body #footer-container .footer   {
  max-width: 970px;
}
body#rbx-body #footer-container .footer-links   {
  margin-top: 20px;
  margin-bottom: 32px;
}
body#rbx-body #footer-container .text-footer-nav   {
  color: var(--rbx21-text-subtle);
  font-size: 16px;
  font-weight: 500;
}
body#rbx-body #footer-container .text-footer-nav:hover,
body#rbx-body #footer-container .text-footer-nav:focus   {
  color: var(--rbx21-text);
  text-decoration: none;
}
body#rbx-body #footer-container .text-footer.footer-note   {
  color: #b8b8b8;
}
body#rbx-body #footer-container .footer-link .text-footer-nav.privacy   {
  color: var(--rbx21-blue);
}

/* Dark-theme footer, as on the 2021 landing page. */
body#rbx-body.dark-theme #footer-container.container-footer {
  background-color: var(--rbx21-dark-footer);
}
body#rbx-body.dark-theme #footer-container .text-footer-nav   {
  color: var(--rbx21-dark-muted);
}
body#rbx-body.dark-theme #footer-container .text-footer-nav:hover,
body#rbx-body.dark-theme #footer-container .text-footer-nav:focus   {
  color: #fff;
}
body#rbx-body.dark-theme #footer-container .text-footer.footer-note   {
  color: var(--rbx21-dark-muted);
}

/* ============================================================
   Error pages (404 / moderation notices)
   ============================================================ */

/*
 * The ban, termination and deletion screens are session-bound and were never
 * captured by the Wayback Machine, so their 2021 layout cannot be reconstructed
 * from evidence. What IS archived is the error-page family those routes fall
 * back to (verified live: /banned serves the standard error page when logged
 * out). Its buttons and headings reuse the legacy classes already themed in
 * this file; the only page-specific rule recoverable from the 2021 bundles
 * is the button width below. The error illustrations themselves are the
 * modern set — the 2021 artwork is not recoverable and was not invented.
 */

body#rbx-body .btn-min-width {
  min-width: 90px;
}

/* Error headings ride the 2021 ramp explicitly, in case a future Roblox
   change stops using h3/h4 for them. */
body#rbx-body .error-title {
  font-size: 20px;
  font-weight: 700;
  color: var(--rbx21-text);
}
body#rbx-body .error-message   {
  font-size: 20px;
  font-weight: 700;
  color: var(--rbx21-text);
}
body#rbx-body.dark-theme .error-title,
body#rbx-body.dark-theme .error-message   {
  color: #fff;
}

/* ============================================================
   Popovers, tooltips and modals
   ============================================================ */

body#rbx-body .popover {
  background-clip: padding-box;
  border: 0;
  border-radius: 4px;
  box-shadow: 0 1px 4px 0 rgba(25, 25, 25, .3);
  max-width: 276px;
}body#rbx-body .light-theme .popover,
body#rbx-body.light-theme .popover {
  background-color: #fff;
  color: var(--rbx21-text);
}body#rbx-body .dark-theme .popover,
body#rbx-body.dark-theme .popover {
  background-color: var(--rbx21-text);
  color: #fff;
}body#rbx-body .light-theme .tooltip-inner,
body#rbx-body.light-theme .tooltip-inner {
  background-color: hsla(0, 0%, 100%, .9);
  color: var(--rbx21-text-subtle);
  font-size: 12px;
  max-width: 220px;
}body#rbx-body .dark-theme .tooltip-inner,
body#rbx-body.dark-theme .tooltip-inner {
  background-color: rgba(0, 0, 0, .7);
  color: var(--rbx21-dark-muted);
}

body#rbx-body .modal-dialog .modal-content   {
  background-color: #fff;
  color: var(--rbx21-text);
  border-radius: 0;
}
body#rbx-body .modal-dialog .modal-content .modal-header   {
  border-bottom: 1px solid var(--rbx21-divider);
  padding: 12px;
  text-align: left;
}
body#rbx-body .modal-dialog .modal-content .modal-body   {
  padding: 12px;
  text-align: left;
}body#rbx-body .dark-theme .modal-dialog .modal-content,
body#rbx-body.dark-theme .modal-dialog .modal-content {
  background-color: var(--rbx21-text);
  color: #fff;
}

body#rbx-body .dropdown-menu,
body#rbx-body .new-dropdown-menu   {
  border-radius: 8px;
}body#rbx-body .light-theme .dropdown-menu,
body#rbx-body.light-theme .dropdown-menu {
  background-color: var(--rbx21-page);
}body#rbx-body .light-theme .dropdown-menu a,
body#rbx-body.light-theme .dropdown-menu a,
body#rbx-body .light-theme .dropdown-menu li a,
body#rbx-body.light-theme .dropdown-menu li a {
  color: var(--rbx21-text-subtle);
}body#rbx-body .light-theme .dropdown-menu a:hover,
body#rbx-body.light-theme .dropdown-menu a:hover {
  color: var(--rbx21-text);
  background-color: rgba(0, 0, 0, .1);
}

/* ============================================================
   Landing page (logged-out home)
   ============================================================ */

#react-landing-container {
  background-color: var(--rbx21-dark-card);
}

/* 2021 game-tile collage plus vignette. The 2021 background scrolled
   with the section, so the modern fixed attachment is relaxed here. */
#react-landing-container .rollercoaster-background {
  background-image: url("  data:image/jpeg;base64,") !important;
  background-position: 50% 50%;
  background-repeat: no-repeat;
  background-size: cover;
  background-attachment: scroll;
}
#react-landing-container .inner-full-height-section   {
  background-image: url("  data:image/png;base64,") !important;
}

#react-landing-container .lower-logo-container   {
  background-color: rgba(0, 0, 0, .5);
}

/* White letterform above the signup card. */
#react-landing-container .header-icon-logo {
  background-image: url("  data:image/png;base64,") !important;
  background-size: contain;
  background-position: 50% 100%;
  background-repeat: no-repeat;
}

#react-landing-container .signup-container.theme-bg   {
  background-color: var(--rbx21-dark-card);
}

#react-landing-container .signup-header   {
  font-size: 20px;
  font-weight: 700;
  text-transform: uppercase;
  color: #fff;
}

#react-landing-container .form-group > label,
#react-landing-container .form-group label.font-caption-header   {
  color: #fff;
  font-size: 12px;
  font-weight: 500;
}

/* Inputs, birthday selects and gender tiles share the dark input treatment. */
#react-landing-container .form-control.input-field,
#react-landing-container input.form-control {
  background-color: var(--rbx21-input-dark);
  color: var(--rbx21-dark-muted);
  border: 1px solid var(--rbx21-input-border-dark);
  border-radius: 8px;
}
#react-landing-container .form-control.input-field::placeholder   {
  color: var(--rbx21-dark-muted);
}

#react-landing-container .rbx-select   {
  background-color: var(--rbx21-input-dark);
  color: var(--rbx21-dark-muted);
  border-radius: 0;
  height: 38px;
}

/* The birthday row reads as one bordered group with hairline dividers. */
#react-landing-container .rbx-select-group {
  border: 1px solid var(--rbx21-input-border-dark);
  border-radius: 8px;
  background-color: var(--rbx21-input-dark);
  overflow: hidden;
}
#react-landing-container .rbx-select-group .rbx-select   {
  border: 0;
  border-radius: 0;
  background-color: transparent;
}
#react-landing-container .rbx-select-group .rbx-select + .rbx-select   {
  border-left: 1px solid var(--rbx21-input-border-dark);
}

#react-landing-container .gender-container .gender-button   {
  background-color: var(--rbx21-input-dark);
  border-color: var(--rbx21-input-border-dark);
}
#react-landing-container .gender-container .gender-button:last-child   {
  border-left-width: 0;
}

#react-landing-container .input-validation,
#react-landing-container .text-error   {
  color: var(--rbx21-red);
}

#react-landing-container .signup-legal-text a,
#react-landing-container .legal-text a,
#react-landing-container a.text-link   {
  color: var(--rbx21-blue);
}

/* White rounded buttons on the dark card, as in 2021. */
#react-landing-container #main-login-button,
#react-landing-container #signup-button {
  background-color: #fff;
  border: 1px solid #fff;
  color: var(--rbx21-text);
  border-radius: 8px;
}
#react-landing-container #main-login-button   {
  color: var(--rbx21-dark-card);
  width: 140px;
  height: 36px;
  padding: 9px;
}
#react-landing-container #signup-button:hover,
#react-landing-container #main-login-button:hover   {
  background-color: #f2f2f2;
  border-color: #f2f2f2;
}

/* Store row: 2021 badges are white artwork on transparent, 50px tall. */
#react-landing-container #app-stores-container,
#react-landing-container .app-stores-container {
  padding: 40px 0 18px;
}
#react-landing-container #app-stores-devices,
#react-landing-container .content-emphasis.text-heading-small   {
  color: #fff;
  text-transform: uppercase;
  margin-bottom: 12px;
}

/* The badge artwork rides on the anchor, which needs box dimensions.
   2021 badges were borderless transparent art; only Xbox carried a hairline. */
#react-landing-container a[href*="apple.com"] {
  background-image: url("  data:image/svg+xml;base64,");
  background-repeat: no-repeat;
  background-size: 100% auto;
  display: inline-block;
  width: 150px;
  height: 50px;
  margin: 6px;
  border: 0;
  background-color: transparent;
  box-shadow: none;
}
#react-landing-container a[href*="play.google.com"]   {
  background-image: url("  data:image/svg+xml;base64,");
  background-repeat: no-repeat;
  background-size: 100% auto;
  display: inline-block;
  width: 171px;
  height: 50px;
  margin: 6px;
  border: 0;
  background-color: transparent;
  box-shadow: none;
}
#react-landing-container a[href*="amazon.com"]   {
  background-image: url("  data:image/png;base64,");
  background-repeat: no-repeat;
  background-size: 100% auto;
  display: inline-block;
  width: 170px;
  height: 50px;
  margin: 6px;
  border: 0;
  background-color: transparent;
  box-shadow: none;
}
#react-landing-container a[href*="microsoft.com"]   {
  background-image: url("  data:image/svg+xml;base64,");
  background-repeat: no-repeat;
  background-size: 100% auto;
  display: inline-block;
  width: 140px;
  height: 50px;
  margin: 6px;
  border: 0;
  background-color: transparent;
  box-shadow: none;
}
#react-landing-container a[href*="xbox.com"]   {
  background-image: url("  data:image/png;base64,");
  background-repeat: no-repeat;
  background-size: 100% auto;
  display: inline-block;
  width: 143px;
  height: 50px;
  margin: 6px;
  border: 1px solid #9f9e9e;
  background-color: transparent;
  box-shadow: none;
  background-position: 50% 50%;
}
#react-landing-container a[href*="apple.com"] img,
#react-landing-container a[href*="play.google.com"] img,
#react-landing-container a[href*="amazon.com"] img,
#react-landing-container a[href*="microsoft.com"] img,
#react-landing-container a[href*="xbox.com"] img   {
  visibility: hidden;
}

/* Eight badges cannot fit the 2021 five-badge row; let it wrap centered. */
#react-landing-container div:has(> a[href*="apple.com"]) {
  flex-wrap: wrap;
  justify-content: center;
}

/* The 2021 submit button showed solid white even before the form was valid. */
#react-landing-container #signup-button {
  opacity: 1;
}

/* ============================================================
   Responsive adjustments (2021 breakpoints)
   ============================================================ */

/* Wide desktops got the tall header with the full wordmark. */
@media (min-width: 1688px) {
  #header.rbx-header   {
    height: 90px;
  }
  body#rbx-body .container-main   {
    margin-top: 90px;
  }
  #header .rbx-navbar-header   {
    max-width: 120px;
    margin: 0 12px;
  }
  #header .icon-logo   {
    display: block;
    background-image: url("  data:image/svg+xml;base64,");
    background-size: 118px 30px;
    width: 118px;
    height: 30px;
  }
  #header .icon-logo-r   {
    display: none;
  }
  #header #header-menu-icon.rbx-nav-collapse   {
    display: none;
  }
}

@media (max-width: 1199px) {
  #header .rbx-navbar-header   {
    margin: 0 5px;
  }
}

@media (max-width: 991px) {
  #header .rbx-navbar-header   {
    max-width: 76px;
    margin: 0 5px;
  }
  body#rbx-body .rbx-left-col   {
    top: 40px;
  }
}

@media (max-width: 767px) {
  #react-landing-container .header-icon-logo   {
    height: 44px;
  }
  #react-landing-container a[href*="apple.com"],
  #react-landing-container a[href*="play.google.com"],
  #react-landing-container a[href*="amazon.com"],
  #react-landing-container a[href*="microsoft.com"],
  #react-landing-container a[href*="xbox.com"]   {
    margin: 4px;
  }
}
